import React from "react";
import { Link } from "react-router-dom";

// Форматирование даты и времени
const formatMatchTime = (utcDate) => {
  if (!utcDate) return { date: "", time: "" };
  const d = new Date(utcDate);

  const dateStr = d.toLocaleDateString("ru-RU", {
    day: "2-digit",
    month: "2-digit",
  });

  const timeStr = d.toLocaleTimeString("ru-RU", {
    hour: "2-digit",
    minute: "2-digit",
  });

  return { date: dateStr, time: timeStr };
};

const getOutcomeColor = (outcome) => {
  if (outcome === "Win Home")
    return { text: "Прогноз: П1", colorClasses: "bg-green-600 text-white" };
  if (outcome === "Win Away")
    return { text: "Прогноз: П2", colorClasses: "bg-red-600 text-white" };
  if (outcome === "Draw")
    return { text: "Прогноз: X", colorClasses: "bg-yellow-500 text-black" };
  return null;
};

function MatchItem({ match }) {
  const predictionData = match.prediction
    ? getOutcomeColor(match.prediction.outcome)
    : null;

  const { date, time } = formatMatchTime(match.utcDate);

  const TeamSection = ({ team }) => {
    const [imgError, setImgError] = React.useState(false);

    return (
      <div className="flex flex-col items-center text-center w-2/5">
        <div className="h-16 w-16 mb-2 flex items-center justify-center">
          {team.logo_url && !imgError ? (
            <img
              src={team.logo_url}
              alt={team.name}
              className="h-full w-full object-contain drop-shadow-md"
              onError={() => setImgError(true)}
            />
          ) : (
            <div className="h-full w-full bg-gradient-to-br from-gray-700 to-gray-900 rounded-full flex items-center justify-center border border-gray-600 shadow-inner">
              <span className="text-xl font-bold text-gray-400">
                {team.name.substring(0, 1)}
              </span>
            </div>
          )}
        </div>
        <span className="text-sm font-black text-white truncate w-full">
          {team.name}
        </span>
      </div>
    );
  };

  return (
    <Link
      to={`/match/${match.id}`}
      className="block bg-gray-900 rounded-xl shadow-2xl border border-gray-800 overflow-hidden
                 transform hover:-translate-y-1 hover:border-gray-600 transition-all duration-300 ease-in-out"
    >
      <div className="p-5 md:p-6 flex flex-col h-full relative">
        {/* Индикатор слева */}
        <div className="absolute top-0 left-0 w-1.5 h-full bg-red-600 opacity-80"></div>

        <div className="pl-2">
          {/* ВЕРХНЯЯ СЕКЦИЯ: КОМАНДЫ И ВРЕМЯ */}
          <div className="flex justify-around items-center mb-6">
            <TeamSection team={match.homeTeam} />

            <div className="flex flex-col items-center justify-center px-2">
              <div className="flex flex-col items-center leading-none mb-2">
                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-1">
                  {date}
                </span>
                <span className="text-2xl font-black text-white tracking-tighter">
                  {time}
                </span>
              </div>
              <span className="text-xs font-black text-gray-800 italic uppercase">
                VS
              </span>
            </div>

            <TeamSection team={match.awayTeam} />
          </div>

          {/* СЕКЦИЯ ПРОГНОЗА (УКРУПНЕНА) */}
          {predictionData && (
            <div className="mt-4 mb-2 text-center bg-white/5 py-4 rounded-xl border border-white/10 backdrop-blur-sm">
              <div className="flex flex-col gap-2 items-center">
                <span
                  className={`px-6 py-1.5 text-xs uppercase font-black rounded-lg shadow-lg tracking-wider ${predictionData.colorClasses}`}
                >
                  {predictionData.text}
                </span>
                <span className="text-gray-400 text-sm font-bold uppercase tracking-widest">
                  Счет:{" "}
                  <span className="text-white text-lg font-black ml-1">
                    {match.prediction.exact_score}
                  </span>
                </span>
              </div>
            </div>
          )}

          {/* Результат для завершенных матчей */}
          {match.status === "FINISHED" && (
            <div className="text-center my-4">
              <span className="text-3xl font-black text-yellow-500 tracking-tighter bg-yellow-500/10 px-4 py-1 rounded-lg">
                {match.score.home} : {match.score.away}
              </span>
            </div>
          )}

          {/* Neural Analysis Loading */}
          {!predictionData && match.status !== "FINISHED" && (
            <div className="my-4 h-12 flex items-center justify-center">
              <span className="text-gray-700 text-[11px] animate-pulse uppercase tracking-[0.3em] font-black">
                Neural Analyzing...
              </span>
            </div>
          )}
        </div>
      </div>
    </Link>
  );
}

export default MatchItem;
